import {analyzeDNA,compareDNA,teachingDNA,aminoAcids,geneChallenges,matchesGeneChallenge} from './studio-science.js';
export function createGeneCraft(root,api){
 let sequence=teachingDNA,challenge='silent',selection=-1,audioContext=null,timer=0,audioToken=0,dragIndex=-1;
 root.innerHTML=`<div class="studio-section-head"><div><span class="studio-kicker">02 / GENECRAFT</span><h2>Chạm vào mã. Nhìn thấy thay đổi.</h2><p>Một đoạn DNA giáo khoa, bốn thử thách. Thử đổi một nucleotide và theo dõi thông tin đi từ DNA đến chuỗi amino acid.</p></div><span class="studio-label">LỚP 10 · 12</span></div><div class="gene-layout"><aside class="gene-missions"><h3>Chọn một câu hỏi</h3><div class="gene-challenges">${geneChallenges.map((c,i)=>`<button type="button" data-gene-challenge="${c.id}"><span>0${i+1}</span><strong>${c.name}</strong><span class="challenge-check" aria-hidden="true"></span></button>`).join('')}</div><div class="gene-challenge-card"><span class="studio-kicker">GIẢ THUYẾT CỦA BẠN</span><p id="gene-challenge-prompt"></p><details id="gene-hint"><summary>Mở một gợi ý</summary><p></p><button type="button" id="gene-example" class="studio-text-button">Nạp ví dụ để đối chiếu ↗</button></details><button type="button" id="gene-check" class="studio-button">Kiểm tra bằng trình tự</button><p id="gene-challenge-feedback" role="status"></p></div></aside><div class="gene-workbench"><div class="gene-editor-heading"><span class="studio-kicker">BÀN THAO TÁC / DNA</span><button type="button" id="gene-reset" class="studio-text-button">Khôi phục đối chứng ↺</button></div><label for="gene-input">Mạch mã hóa DNA, chiều 5′ → 3′</label><textarea id="gene-input" rows="2" maxlength="180" spellcheck="false" autocapitalize="characters" aria-describedby="gene-input-help">${teachingDNA}</textarea><p id="gene-input-help" class="studio-fineprint">Nhập A, C, G, T; tối đa 90 nucleotide. Đoạn nhân tạo không có intron, chỉ xét khung đọc từ ATG đầu tiên ở vị trí 1.</p><div class="gene-base-tools"><span>Chạm một base để chọn:</span><div id="gene-bases" class="gene-bases"></div><div class="studio-button-row gene-edit-controls"><button type="button" data-gene-base="A">A</button><button type="button" data-gene-base="T">T</button><button type="button" data-gene-base="G">G</button><button type="button" data-gene-base="C">C</button><button type="button" id="gene-delete">Xóa base</button><button type="button" id="gene-insert">Chèn A sau base</button></div></div><p id="gene-error" class="studio-error" role="status"></p><div class="gene-flow"><div><span>MẠCH KHUÔN · 3′ → 5′</span><code id="gene-template"></code></div><span class="gene-flow-arrow" aria-hidden="true">↓ Phiên mã (giản lược)</span><div><span>mRNA · 5′ → 3′</span><code id="gene-rna"></code></div><span class="gene-flow-arrow" aria-hidden="true">↓ Dịch mã · khung đọc đã chọn</span></div><div id="gene-codons" class="gene-codons" aria-label="Bộ ba và amino acid"></div><p class="studio-fineprint">Kéo một thẻ bộ ba để đổi chỗ. Các nút ← → thực hiện cùng thao tác bằng bàn phím hoặc cảm ứng. Phần sau STOP không được dịch.</p><div class="gene-protein" id="gene-protein"><span class="studio-kicker">CHUỖI AMINO ACID · ĐẦU N → C</span><div id="gene-protein-chain"></div><span id="gene-protein-caption"></span></div><div id="gene-comparison" class="gene-comparison" aria-live="polite"></div><div class="studio-button-row"><button type="button" id="gene-save" class="studio-button">Lưu khám phá vào sổ</button><button type="button" id="gene-sound" class="studio-button secondary" aria-pressed="false">♫ Nghe chuỗi amino acid</button></div><p class="studio-fineprint">BioSound ánh xạ amino acid thành nốt nhạc theo quy ước nghệ thuật. Đây không phải âm thanh tự nhiên của DNA. Không suy ra chức năng protein hay kiểu hình từ đoạn ngắn này.</p></div></div>`;
 const input=root.querySelector('#gene-input');
 function stopSound(){audioToken++;clearTimeout(timer);if(audioContext&&audioContext.state!=='closed')audioContext.close().catch(()=>{});audioContext=null;const b=root.querySelector('#gene-sound');b.textContent='♫ Nghe chuỗi amino acid';b.setAttribute('aria-pressed','false')}
 function render(){const result=analyzeDNA(sequence),compare=compareDNA(teachingDNA,sequence);root.querySelector('#gene-error').textContent=result.valid?'':result.error;root.querySelector('#gene-template').textContent=result.valid?result.template:'—';root.querySelector('#gene-rna').textContent=result.valid?result.mrna:'—';
  root.querySelector('#gene-bases').innerHTML=result.valid?[...result.dna].map((b,i)=>`<button type="button" data-base-index="${i}" class="base-${b}${selection===i?' selected':''}${teachingDNA[i]!==b?' changed':''}" aria-label="Base ${i+1}: ${b}" aria-pressed="${selection===i}">${b}<small>${i+1}</small></button>`).join(''):'';
  root.querySelectorAll('[data-base-index]').forEach(b=>b.addEventListener('click',()=>{selection=Number(b.dataset.baseIndex);render();root.querySelector(`[data-base-index="${selection}"]`)?.focus()}));
  root.querySelectorAll('.gene-edit-controls button').forEach(b=>b.disabled=!result.valid||selection<0||selection>=result.dna.length);
  root.querySelector('#gene-codons').innerHTML=result.valid?result.codons.map((c,i)=>`<div class="gene-codon ${c.afterStop?'after-stop':''} ${c.aa==='*'?'stop-codon':''}" draggable="true" data-codon-index="${i}"><span>${i+1}</span><strong>${c.rna}</strong><b>${c.aa?aminoAcids[c.aa][0]:'Thiếu base'}</b><div><button type="button" data-move-codon="${i}" data-direction="-1" aria-label="Chuyển bộ ba ${i+1} sang trái" ${i===0?'disabled':''}>←</button><button type="button" data-move-codon="${i}" data-direction="1" aria-label="Chuyển bộ ba ${i+1} sang phải" ${i===result.codons.length-1?'disabled':''}>→</button></div></div>`).join(''):'';
  root.querySelector('#gene-protein>div').innerHTML=result.valid&&result.starts?result.protein.map((a,i)=>`<span class="amino-acid" style="--aa-hue:${70+'ACDEFGHIKLMNPQRSTVWY'.indexOf(a)*6}" title="${aminoAcids[a][1]}">${aminoAcids[a][0]}<small>${i+1}</small></span>`).join('<i aria-hidden="true"></i>'):'<p>Chưa có chuỗi dịch từ vị trí bắt đầu đã chọn.</p>';
  root.querySelector('#gene-protein-caption').textContent=!result.valid?'':!result.starts?'Thiếu ATG ở đầu: không tự tìm khung đọc khác.':`${result.protein.length} amino acid · ${result.terminated?'Đã gặp codon dừng':'Chưa có codon dừng trong đoạn minh họa'}${result.partial?' · Có bộ ba chưa đủ nucleotide':''}`;
  const comparison=root.querySelector('#gene-comparison');comparison.dataset.type=compare.type;comparison.replaceChildren(Object.assign(document.createElement('strong'),{textContent:compare.label}),Object.assign(document.createElement('p'),{textContent:compare.text}));
  root.querySelector('#gene-save').disabled=!result.valid;root.querySelector('#gene-sound').disabled=!result.valid||!result.protein.length;
  root.querySelectorAll('[data-gene-challenge]').forEach(b=>{const chosen=b.dataset.geneChallenge===challenge;b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',String(chosen));b.querySelector('.challenge-check').textContent=api.isComplete('gene-'+b.dataset.geneChallenge)?'✓':''});
 }
 function change(next){stopSound();sequence=next;input.value=next;selection=Math.min(selection,next.length-1);root.querySelector('#gene-challenge-feedback').textContent='';render()}
 function choose(id){challenge=id;const c=geneChallenges.find(x=>x.id===id);root.querySelector('#gene-challenge-prompt').textContent=c.prompt;root.querySelector('#gene-hint p').textContent=c.hint;root.querySelector('#gene-hint').open=false;root.querySelector('#gene-challenge-feedback').textContent='';change(teachingDNA)}
 input.addEventListener('input',()=>{stopSound();sequence=input.value;selection=-1;root.querySelector('#gene-challenge-feedback').textContent='';render()});
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.geneChallenge)choose(b.dataset.geneChallenge);if(b.dataset.geneBase){const r=analyzeDNA(sequence);if(r.valid&&selection>=0)change(r.dna.slice(0,selection)+b.dataset.geneBase+r.dna.slice(selection+1))}if(b.dataset.moveCodon!==undefined)moveCodon(Number(b.dataset.moveCodon),Number(b.dataset.moveCodon)+Number(b.dataset.direction))});
 function moveCodon(from,to){const r=analyzeDNA(sequence);if(!r.valid||from===to||to<0||to>=r.codons.length)return;const chunks=r.codons.map(c=>c.codon),[chunk]=chunks.splice(from,1);chunks.splice(to,0,chunk);selection=-1;change(chunks.join(''));root.querySelector(`[data-move-codon="${to}"]`)?.focus()}
 root.addEventListener('dragstart',e=>{const card=e.target.closest('[data-codon-index]');if(card){dragIndex=Number(card.dataset.codonIndex);e.dataTransfer.setData('text/plain',String(dragIndex));e.dataTransfer.effectAllowed='move'}});root.addEventListener('dragover',e=>{if(e.target.closest('[data-codon-index]'))e.preventDefault()});root.addEventListener('drop',e=>{const card=e.target.closest('[data-codon-index]');if(card&&dragIndex>=0){e.preventDefault();moveCodon(dragIndex,Number(card.dataset.codonIndex))}dragIndex=-1});root.addEventListener('dragend',()=>{dragIndex=-1});
 root.querySelector('#gene-reset').addEventListener('click',()=>change(teachingDNA));root.querySelector('#gene-example').addEventListener('click',()=>change(geneChallenges.find(x=>x.id===challenge).preset));
 root.querySelector('#gene-delete').addEventListener('click',()=>{const r=analyzeDNA(sequence);if(r.valid&&selection>=0)change(r.dna.slice(0,selection)+r.dna.slice(selection+1))});root.querySelector('#gene-insert').addEventListener('click',()=>{const r=analyzeDNA(sequence);if(r.valid&&selection>=0&&r.dna.length<90)change(r.dna.slice(0,selection+1)+'A'+r.dna.slice(selection+1))});
 root.querySelector('#gene-check').addEventListener('click',()=>{const ok=matchesGeneChallenge(challenge,sequence);root.querySelector('#gene-challenge-feedback').textContent=ok?'Đã kiểm chứng! Đối chiếu bộ ba và chuỗi amino acid để giải thích điều vừa xảy ra.':'Trình tự chưa thỏa đủ điều kiện của thử thách. Đọc lại yêu cầu, đối chiếu vị trí thay đổi và thử một giả thuyết khác.';if(ok){api.award('gene-'+challenge,'Một giả thuyết đã được kiểm chứng');render()}});
 root.querySelector('#gene-save').addEventListener('click',()=>{const r=analyzeDNA(sequence),c=compareDNA(teachingDNA,sequence);if(r.valid)api.saveNote(`GeneCraft: ${c.label}`,`Mạch mã hóa 5′→3′: ${r.dna}\nMạch khuôn 3′→5′: ${r.template}\nmRNA 5′→3′: ${r.mrna}\nChuỗi amino acid: ${r.protein.map(a=>aminoAcids[a][0]).join(' – ')||'Không dịch trong khung đã chọn'}\n${c.text}\n\nĐoạn giáo khoa nhân tạo, bảng mã chuẩn NCBI số 1. Không suy ra kiểu hình.`)});
 root.querySelector('#gene-sound').addEventListener('click',async()=>{if(audioContext){stopSound();return}const r=analyzeDNA(sequence);if(!r.valid||!r.protein.length)return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){api.toast('Trình duyệt này chưa hỗ trợ Web Audio.');return}try{audioContext=new Audio();const ctx=audioContext,token=++audioToken;await ctx.resume();if(token!==audioToken||ctx.state==='closed')return;const start=ctx.currentTime+.08,letters='ACDEFGHIKLMNPQRSTVWY',pentatonic=[0,2,4,7,9];r.protein.forEach((a,i)=>{const n=letters.indexOf(a),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=220*2**((pentatonic[n%5]+12*Math.floor(n/5))/12);gain.gain.setValueAtTime(0,start+i*.33);gain.gain.linearRampToValueAtTime(.055,start+i*.33+.03);gain.gain.exponentialRampToValueAtTime(.001,start+i*.33+.3);osc.connect(gain);gain.connect(ctx.destination);osc.start(start+i*.33);osc.stop(start+i*.33+.32)});const b=root.querySelector('#gene-sound');b.textContent='■ Dừng bản nhạc';b.setAttribute('aria-pressed','true');timer=setTimeout(stopSound,r.protein.length*330+300)}catch{stopSound();api.toast('Chưa phát được âm thanh. Thử lại bằng nút nghe.')}});
 choose(challenge);return {setActive(value){if(!value)stopSound()},refresh:render};
}
